181	    @ResponseBody
182	    public ResponseEntity<ProblemDetail> handleInvalidOwnerFieldsException(InvalidOwnerFieldsException e, HttpServletRequest request) {
183	        logger.debug("Invalid owner fields at {} {}: {}",
184	            request.getMethod(),
185	            request.getRequestURI(),
186	            e.getFields());
187	        HttpStatus status = HttpStatus.BAD_REQUEST;
188	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
189	        detail.setProperty("errors", e.getFields());
190	        return ResponseEntity.status(status).body(detail);
191	    }
192	
193	    /**
194	     * Handles {@link DuplicateTelephoneException} raised when an owner is created with a normalized
195	     * telephone number already used by another owner. Returns a 409 Conflict.
196	     *
197	     * @param e The {@link DuplicateTelephoneException} to be handled
